"use strict";(globalThis.webpackChunkgrc||=[]).push([[42683],{64725(e){e.exports=JSON.parse('{"citeKey":"bateman2026aes","slug":"bateman-2026-agent-error-simulator-3c7d","title":"Agent Error Simulator: Fault Injection for Testing Recovery in Agentic Workflows","authors":["K. Bateman","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Multi-agent large language model (LLM) workflows are increasingly deployed for complex, multi-step computational tasks. Yet the fault tolerance of these systems (how individual agents respond to malformed inputs, tool failures, and subtle numerical errors) remains poorly characterized. We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection. AES intercepts agent-to-model HTTP traffic via a transparent proxy, injecting three categories of faults (format, logic, and tool call) at configurable points in a hierarchical planner-worker-aggregator workflow. We evaluate four models spanning 2B\u201332B parameters (Qwen2.5-Coder 32B, Gemma4 27B, Mistral 7B, and Granite4 2B) across 194 jobs organized into 10 test groups covering baseline behavior, multi-error injection, workflow scale, context pressure, compaction, and detection timing. Our results reveal a model-size-dependent logic error recovery threshold between 7B and 27B parameters; universal catastrophic failure under aggregator-level logic injection; and model-specific aggregator arithmetic deficits that interact with injected faults in non-obvious ways. We release the benchmark suite, injection tooling, and result data to support reproducible multi-agent fault tolerance research.","hasAbstract":true,"lede":"We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection.","links":{"pdf":"https://grc.iit.edu/papers/2026/bateman-2026-agent-error-simulator-3c7d.pdf"},"tags":["LLM Agents","Fault Injection","Resilience","Multi-Agent Workflows"],"_projectIds":["dtio","storehub","iowarp"],"grcSelected":false,"status":"presented","visibility":"public","projectIds":["iowarp","dtio","storehub"],"memberAuthors":["bateman-keith","cernuda-jaime","logan-luke","nicolae-bogdan","cappello-franck","sun-xian-he","kougkas-anthony"],"funding":[{"agency":"NSF","award":"CNS-2346504","projectId":"storehub"},{"agency":"NSF","award":"CSSI-2411386"},{"agency":"NSF","award":"OAC-2411318","projectId":"iowarp"},{"agency":"NSF","award":"OAC-2320345"},{"agency":"DOE","award":"DE-SC0024593","projectId":"dtio"},{"agency":"ANL","award":"DE-AC02-06CH11357"}]}')}}]);